import { test } from 'node:test';
import assert from 'node:assert/strict';
import { chromium } from 'playwright';
import { startControlPageServer } from '../src/mastra/control-page.ts';
import { createBuildRunnerClient, BuildJobSchema } from '../src/mastra/build-client.ts';

const card = {
  identifier: 'JUL-232',
  title: 'Practice',
  state: 'Ready',
  description: '## Agent Brief\n\n**Category:** machinery\n\n**Summary:** Practice\n\n**Current behavior:** Missing marker\n\n**Desired behavior:** Add marker\n\n**Key interfaces:** marker\n\n**Acceptance criteria:** exact marker\n\n**Out of scope:** Review'
};

const offer = {
  route: 'commandcode',
  modelId: 'reflection/beam:free',
  name: 'Beam',
  company: 'Reflection',
  service: 'CommandCode',
  codingCapable: true,
  supportedEfforts: ['medium'],
  wire: 'chat'
};

const iso = new Date('2025-07-23T12:00:00.000Z').toISOString();
const roles = { orchestrator: offer, coder: offer };
const snapshot = { runId: 'jul-232-ui-test', card, roles, state: 'ready-for-build', initializedAt: iso };
const initResult = { runId: snapshot.runId, state: 'ready-for-build', snapshot, resumed: false };
const candidateCommit = 'b'.repeat(40);

const job = BuildJobSchema.parse({
  snapshot,
  runnerPid: 123,
  workerPid: 124,
  worktree: '/tmp/practice',
  baseCommit: 'a'.repeat(40),
  state: 'running',
  result: null,
  error: null
});

const activity = {
  roleDispatches: { builder: 0, reviewer: 0, crashFixer: 0, crashReviewer: 0 },
  llmInferenceCalls: 0,
  linearQueries: 0,
  linearMutations: 0
};

const savedResult = {
  state: 'ready-for-review',
  card,
  roles,
  actualModels: {
    orchestrator: 'commandcode-free/reflection/beam:free',
    coder: 'commandcode-free/reflection/beam:free'
  },
  threadId: 'thread-test',
  worktree: '/tmp/practice',
  baseCommit: 'a'.repeat(40),
  candidateCommit,
  account: { spentNano: 0, heldNano: 0, stopped: false },
  internalReview: { verified: true },
  downstreamReviewStarted: false,
  completedAtISO: iso
};

test('control page shows running then saved review result', async () => {
  let buildJobs: any[] = [];
  let startCount = 0;
  const startInitialization = async (receivedCard: any, receivedRoles: any) => {
    assert.deepEqual(receivedCard, card);
    assert.deepEqual(receivedRoles, roles);
    startCount += 1;
    buildJobs = [job];
    return initResult;
  };

  const server = await startControlPageServer({
    port: 0,
    cards: [card],
    offers: [offer],
    getBuildJobs: () => buildJobs,
    startInitialization,
    getRuns: () => ({ runs: [], totalRuns: 0 }),
    getActivity: () => activity
  });

  const browser = await chromium.launch();
  try {
    const page = await browser.newPage();
    await page.goto(server.url);

    const cardSelect = page.locator('select').filter({ has: page.locator('option', { hasText: 'Ready' }) }).first();
    await cardSelect.selectOption({ label: /Ready/ });

    for (const legendText of ['Orchestrator', 'Coder']) {
      const fieldset = page.locator('fieldset', { has: page.locator('legend', { hasText: legendText }) });
      await fieldset.locator('select').selectOption({ index: 0 });
    }

    await page.getByRole('button', { name: /Start/i }).click();
    await page.getByText(/running/i).waitFor({ state: 'visible', timeout: 10000 });

    job.state = 'ready-for-review';
    job.result = savedResult;
    buildJobs = [job];

    await page.getByText(candidateCommit).waitFor({ state: 'visible', timeout: 10000 });
    await page.reload();
    await page.getByText(candidateCommit).waitFor({ state: 'visible', timeout: 10000 });
    await page.getByText(/ready-for-review/i).waitFor({ state: 'visible', timeout: 10000 });
    await page.getByText('Downstream Review has not started').waitFor({ state: 'visible', timeout: 10000 });

    assert.equal(startCount, 1);
  } finally {
    await browser.close();
    await server.close();
  }
});

test('build runner client captures init and validates jobs', async () => {
  const calls: any[] = [];
  const fetchImpl = async (input: any, init: any) => {
    calls.push({ input, init });
    return new Response(JSON.stringify(initResult), {
      status: 200,
      headers: { 'content-type': 'application/json' }
    });
  };

  const makeClient = (impl: any) => {
    try {
      return createBuildRunnerClient({ baseUrl: 'http://runner.test', fetchImpl: impl });
    } catch {
      return createBuildRunnerClient('http://runner.test', { fetchImpl: impl });
    }
  };

  const client = makeClient(fetchImpl);
  const start = (client as any).startInitialization ?? (client as any).start ?? (client as any).initialize;
  const returned = await start(card, roles);
  assert.deepEqual(returned, initResult);
  assert.equal(calls.length, 1);
  assert.equal(calls[0].init.method, 'POST');
  assert.deepEqual(JSON.parse(calls[0].init.body), { card, roles });

  const readyJob = BuildJobSchema.parse({
    snapshot,
    runnerPid: 123,
    workerPid: 124,
    worktree: '/tmp/practice',
    baseCommit: 'a'.repeat(40),
    state: 'ready-for-review',
    result: savedResult,
    error: null
  });

  const listImpl = async () => new Response(JSON.stringify([readyJob]), {
    status: 200,
    headers: { 'content-type': 'application/json' }
  });
  const listClient = makeClient(listImpl);
  const list = (listClient as any).getBuildJobs ?? (listClient as any).listBuildJobs ?? (listClient as any).listJobs;
  const jobs = await list();
  assert.deepEqual(jobs, [readyJob]);

  const invalid = { ...readyJob, result: null };
  const invalidImpl = async () => new Response(JSON.stringify([invalid]), {
    status: 200,
    headers: { 'content-type': 'application/json' }
  });
  const invalidClient = makeClient(invalidImpl);
  const invalidList = (invalidClient as any).getBuildJobs ?? (invalidClient as any).listBuildJobs ?? (invalidClient as any).listJobs;
  await assert.rejects(invalidList());
  assert.throws(() => BuildJobSchema.parse(invalid));
});
